package org.schoolkernel.workspace;

import static org.junit.jupiter.api.Assertions.*;
import com.microsoft.playwright.APIResponse;
import com.microsoft.playwright.options.RequestOptions;
import org.junit.jupiter.api.Test;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.node.ObjectNode;

class DefinitionFinishBrowserIT extends WorkbenchBrowserSupport {
    @Test void initialExactFinishCancelReloadAndContextSurvivesAcceptance(){
        initial(false);open();ObjectNode doc=(ObjectNode)storedWorkspaceDocument();doc.withObject("definitionDraft").withObject("editingContext").putObject("requirements").putObject("retained-series").put("seriesId","retained-series").put("cohortId","cohort-7a").put("subjectId","math").put("count",0).putObject("defaults").put("teacherId","teacher-alex");store(doc);workbench.reload();JsonNode draft=storedWorkspaceDocument().path("definitionDraft");String before=storedDocument();finishDialog();page().getByText("Cancel finish",new com.microsoft.playwright.Page.GetByTextOptions().setExact(true)).click();assertEquals(before,storedDocument());finishDialog();page().locator("#confirm-definition-finish").click();workbench.awaitText("Initial draft");assertEquals("INITIAL_DRAFT",storedLifecycle());assertEquals(draft.path("definition"),storedWorkspaceDocument().path("initialDefinition"));assertEquals(draft.path("editingContext"),storedWorkspaceDocument().path("authoringContext"));assertTrue(storedWorkspaceDocument().path("definitionRevision").asString().matches("sha256:[0-9a-f]{64}"));assertFalse(storedWorkspaceDocument().has("acceptedBaseline"));workbench.reload();assertEquals(draft.path("definition"),storedWorkspaceDocument().path("initialDefinition"));
    }
    @Test void acceptedFinishSeedsWholeSuccessorRetainsExactDraftAndCurrent(){
        ObjectNode source=fixtures.validAcceptedDocument();storeAccepted(source);workbench.open();open();ObjectNode doc=(ObjectNode)storedWorkspaceDocument();ObjectNode draft=doc.withObject("definitionDraft"),definition=draft.withObject("definition");definition.put("displayName","Authored successor");((ObjectNode)definition.path("teachers").get(0)).putArray("undesirablePeriodIds");draft.put("draftRevision",DefinitionDraftService.revision(definition));store(doc);workbench.reload();JsonNode retained=storedWorkspaceDocument().path("definitionDraft").deepCopy();finishDialog();page().locator("#confirm-definition-finish").click();workbench.awaitText("Repair draft");assertEquals("REPAIR_DRAFT",storedLifecycle());JsonNode saved=storedWorkspaceDocument();assertEquals(source.path("acceptedBaseline"),saved.path("acceptedBaseline"));assertEquals(source.path("school"),saved.path("school"));assertEquals(retained,saved.path("repairDraft").path("retainedAuthoring"));assertEquals(retained.path("definition"),saved.path("repairDraft").path("seedDefinition"));assertEquals(source.path("acceptedBaseline").path("result").path("inputRevision"),saved.path("repairDraft").path("seedDefinition").path("basedOnRevision"));assertFalse(saved.has("proposal"));workbench.reload();assertEquals(saved,storedWorkspaceDocument());
    }
    @Test void zeroLessonsAdvisoriesAllowedAndBlockersRefused(){
        initial(true);open();finishDialog();workbench.awaitText("No lessons configured; planning will produce an empty timetable");page().locator("#confirm-definition-finish").click();workbench.awaitText("Initial draft");assertTrue(storedWorkspaceDocument().path("initialDefinition").path("lessons").isEmpty());
        open();ObjectNode doc=(ObjectNode)storedWorkspaceDocument();doc.withObject("definitionDraft").withObject("definition").put("displayName","");store(doc);workbench.reload();String before=storedDocument();finishDialog();assertTrue(page().locator("#confirm-definition-finish").isDisabled());assertEquals(409,command("finish",envelope()).status());assertEquals(before,storedDocument());
    }
    @Test void kernelDisplaysEveryUnknownFieldAndLocationWithoutLoss(){
        initial(false);open();ObjectNode doc=(ObjectNode)storedWorkspaceDocument(),definition=doc.withObject("definitionDraft").withObject("definition");definition.put("unknownRoot","preserved");((ObjectNode)definition.path("teachers").get(0)).put("unknownTeacher","preserved");store(doc);workbench.reload();String before=storedDocument();finishDialog();page().locator("#confirm-definition-finish").click();workbench.awaitText("unknownRoot");workbench.awaitText("unknownTeacher");workbench.awaitText("/teachers/0");assertEquals(before,storedDocument());assertEquals("DEFINITION_DRAFT",storedLifecycle());
    }
    @Test void staleReviewAndStorageFailureRetainWholeDraft()throws Exception{
        initial(false);open();JsonNode confirmation=envelope();String oldTag="\"ws-"+storedVersion()+"\"";ObjectNode doc=(ObjectNode)storedWorkspaceDocument();doc.withObject("definitionDraft").withObject("definition").put("displayName","Newer saved title");store(doc);String before=storedDocument();assertEquals(412,command("finish",confirmation,oldTag).status());assertEquals(before,storedDocument());assertEquals(409,command("finish",confirmation).status());assertEquals(before,storedDocument());workbench.reload();finishDialog();withRejectedWorkspaceUpdates("NEW.lifecycle_state='INITIAL_DRAFT'",()->{page().locator("#confirm-definition-finish").click();workbench.awaitText("Local storage is unavailable");assertEquals(before,storedDocument());});page().locator("#confirm-definition-finish").click();workbench.awaitText("Initial draft");assertEquals("Newer saved title",storedWorkspaceDocument().path("initialDefinition").path("displayName").asString());
    }
    @Test void narrowFinishDisabledAndUnsavedStayRetained(){initial(false);open();workbench.viewport(390,844);assertTrue(page().locator("#finish-definition").isDisabled());workbench.expect("document.documentElement.scrollWidth <= innerWidth");workbench.viewport(1280,800);page().locator("button[data-section='School']").click();page().locator("#school-display-name").fill("Unsaved");String before=storedDocument();page().locator("button[data-section='Review']").click();page().locator("#school-stay").click();assertEquals("Unsaved",page().locator("#school-display-name").inputValue());assertEquals(before,storedDocument());}
    private void initial(boolean empty){ObjectNode definition=((ObjectNode)fixtures.validAcceptedDocument().path("acceptedBaseline").path("definition")).deepCopy().put("catalogVersion",9);if(empty)definition.putArray("lessons");ObjectNode doc=JSON.createObjectNode();doc.set("initialDefinition",definition);jdbc.sql("UPDATE workspace_aggregate SET lifecycle_state='INITIAL_DRAFT',version=version+1,document=CAST(:doc AS jsonb) WHERE workspace_id=1").param("doc",JSON.writeValueAsString(doc)).update();workbench.open();}
    private void open(){page().locator("#open-authoring").click();page().locator("#confirm-authoring").click();workbench.awaitText("Saved school-definition draft");page().locator("button[data-section='Review']").click();}
    private void finishDialog(){page().locator("#finish-definition").click();page().locator("#finish-definition-dialog").waitFor();}
    private JsonNode envelope(){JsonNode preview=JSON.readTree(command("finish/preview",JSON.createObjectNode()).text());return JSON.createObjectNode().put("confirmed",true).put("token",preview.path("token").asString());}
    private com.microsoft.playwright.Page page(){return workbench.page();}
    private void store(JsonNode doc){jdbc.sql("UPDATE workspace_aggregate SET version=version+1,document=CAST(:doc AS jsonb) WHERE workspace_id=1").param("doc",JSON.writeValueAsString(doc)).update();}
    private APIResponse command(String route,JsonNode body){return command(route,body,"\"ws-"+storedVersion()+"\"");}
    private APIResponse command(String route,JsonNode body,String tag){String base="http://localhost:"+port;JsonNode csrf=JSON.readTree(page().request().get(base+"/api/csrf").text());return page().request().post(base+"/api/definition-draft/"+route,RequestOptions.create().setHeader("Content-Type","application/json").setHeader("Origin",base).setHeader(csrf.path("headerName").asString(),csrf.path("token").asString()).setHeader("If-Match",tag).setData(JSON.writeValueAsString(body)));}
}
